import{_ as l,a0 as p,w as o,s as r,I as i,x as a,a1 as n,A as t,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const w=JSON.parse('{"title":"一個更好的視頻碼頭 | LCTT x X-CMD","titleTemplate":false,"description":"一個更好的視頻碼頭 | LCTT (202304) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"一個更好的視頻碼頭 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"一個更好的視頻碼頭 | LCTT (202304) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202304/20210111 an even better video wharf","title":"一個更好的視頻碼頭","tag":"202304","desc":""},"relativePath":"202304/20210111 an even better video wharf.md","filePath":"[post].md"}'),u={name:"202304/20210111 an even better video wharf.md"};function m(g,s,k,h,b,c){const e=p("Link");return o(),r("div",null,[s[20]||(s[20]=i("h1",{id:"一個更好的視頻碼頭",tabindex:"-1"},[a("一個更好的視頻碼頭 "),i("a",{class:"header-anchor",href:"#一個更好的視頻碼頭","aria-label":"Permalink to “一個更好的視頻碼頭”"},"​")],-1)),s[21]||(s[21]=i("p",null,[i("img",{src:"https://img.linux.net.cn/data/attachment/album/202304/11/150233vzkt1tute4i4oemg.jpg",alt:""})],-1)),i("p",null,[s[2]||(s[2]=a("之前，",-1)),n(e,{href:"https://jao.io/blog/2021-01-09-embarking-videos.html"},{default:t(()=>[...s[0]||(s[0]=[a("我在寫",-1)])]),_:1}),s[3]||(s[3]=a(" 有關 ",-1)),n(e,{href:"https://github.com/oantolin/embark"},{default:t(()=>[...s[1]||(s[1]=[a("embark",-1)])]),_:1}),s[4]||(s[4]=a(" 的內容，我的第一設備為啓動遠程視頻流設計了一個新的 embark。embark 的作者 Omar Antolín Camarena 不僅閲讀了這篇內容，還點評了一下我認為值得跟進的一些重大改進。",-1))]),s[22]||(s[22]=d(`<p>首先，你應該記得我們曾定義過一個檢測視頻 URL 的函數：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (defun jao-video-finder ()</span></span>
<span class="line"><span>      &quot;Check whether we&#39;re looking at a video URL.</span></span>
<span class="line"><span>    Return (video-url . &lt;URL&gt;) if so.&quot;</span></span>
<span class="line"><span>      (when-let ((url (thing-at-point-url-at-point)))</span></span>
<span class="line"><span>        (when (string-match-p jao-video-url-rx url)</span></span>
<span class="line"><span>          (cons &#39;video-url url))))</span></span></code></pre></div><p>當我們得到了一個非空的 <code>url</code> 值，即便它不是一個視頻鏈接，但它仍然是一個確切的 URL，並且 embark 已有了一個 <code>url</code> 類別，所以我們可以藉助默認的 URL 尋檢器存儲一個新的句法分析,語句如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (when-let ((url (thing-at-point-url-at-point)))</span></span>
<span class="line"><span>      (cons (if (string-match-p jao-video-url-rx url) &#39;video-url &#39;url) url))</span></span></code></pre></div><p>這裏有一個潛在的缺點就是：我們重寫了 embark 的尋檢器，<code>embark-target-url-at-point</code>，所以我們可能更願意保留後者。</p><p>實際上多虧了 embark 的 <em>目標轉換器</em> 我們才能做成。我們可以在 <code>embark-transformers-alist</code> 中添加任意一個函數，應用於任何一個給定類別的目標，而 embark 會將其轉換後的值應用於它的操作中。Omar 很貼切地把這個過程稱為“目標的精化”;我們具體做法如下：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (defun jao-refine-url-type (url)</span></span>
<span class="line"><span>      &quot;Refine type of URL in case it is a video.&quot;</span></span>
<span class="line"><span>      (cons (if (string-match-p jao-video-url-rx url) &#39;video-url &#39;url) url))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    (add-to-list &#39;embark-transformer-alist &#39;(url . jao-refine-url-type))</span></span></code></pre></div><p>通過這種策略，我們就不再需要 <code>jao-video-finder</code> 了，而且從概念上來説，我們的 <code>video-url</code> 應該被定義為一個精化操作而並非是一個目標 [腳註 1]。Omar 的第二個提議也與這個概念相契合：想必我們都希望所有關於 <code>url</code> 和我們的 <code>video-url</code> 的操作都是可用的，不是嗎？ 唔，這就是為什麼我們用來定義行為的 <code>embark-define-keymap</code> 的宏可以通過使用關鍵字 [腳註 2] <code>:parent</code> 繼承其他鍵映射中已經定義的所有操作的原因：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (embark-define-keymap jao-video-url-map</span></span>
<span class="line"><span>      &quot;Actions on URLs pointing to remote video streams.&quot;</span></span>
<span class="line"><span>      :parent embark-url-map</span></span>
<span class="line"><span>      (&quot;p&quot; jao-play-video-url))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    (add-to-list &#39;embark-keymap-alist &#39;(video-url . jao-video-url-map))</span></span></code></pre></div><p>這種繼承鍵映射的功能並非是 embark 的附屬功能：vanilla Emacs 鍵映射通過標準函數 <code>set-keymap-parent</code> 已經搞定它了。你可以完全不用 <code>embark-define-keymap</code> 來定義 <code>jao-video-url-map</code>，工作原理是一樣的。</p><p>這樣，我們的代碼就能夠更短，特徵更多：謝謝你，Omar！</p><p><strong>腳註 1</strong>：在某些情況下，保留 jao-video-finder 是有意義的，即，如果我們想要改變檢測 URL 的功能的話。例如，我在使用 emacs-w3m 的時候，經常有一個 URL 作為文本屬性儲存了起來(實際文本是個鏈接文本)。要通過那裏檢索 URL，就需要調用 <code>w3m-anchor</code>，而用 <code>embark-target-url-at-point</code> 就會錯過它。對於這種情況，我最終編寫(並使用)<code>jao-video-finder</code> 將其通過下文定義:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (when-let ((url (or (w3m-anchor) (thing-at-point-url-at-point))))</span></span>
<span class="line"><span>      (cons (if (string-match-p jao-video-url-rx url) &#39;video-url &#39;url) url))</span></span></code></pre></div><p>另一種達成同件事情的方式（再次向 Omar 致敬）便是為 w3m 的錨點放置一個特定的巡檢器（且繼續使用 video-url 的轉換器）：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span></span></span>
<span class="line"><span>    (defun jao-w3m-url-finder ()</span></span>
<span class="line"><span>      (when-let ((url (w3m-anchor)))</span></span>
<span class="line"><span>        (cons &#39;url url)))</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    (add-to-list &#39;embark-target-finders #&#39;jao-w3m-url-finder)</span></span></code></pre></div><p>這種方法更加模組化，並且取決於你們的喜好，且更加巧妙。這些功能都很小巧並且兩種方法之間並沒有太大的差別，但是如果其中某一種繼續加入更多尋檢器的話，前一種方法用起來來反而會讓一切變得更糟。</p><p><strong>腳註 2</strong>：在我最開始的例子中，我在視頻地圖中還添加了 <code>browse-url</code> 和 <code>browse-url-firefox</code>。前一個已不再重要，因為它已經在 <code>embark-url-map</code> 中出現過了，如果我們想讓 <code>browse-url-firefox</code> 對 <em>所有</em> 的 URLs 可用,我們可以將其加入到 <code>embark-url-map</code> （謹記，embark 的鍵映射只是 Emacs 的鍵映射）。這是另一種擴展 embark 的簡便方法。</p><p><em>（題圖：MJ:emacs video geek wallpaper dark plain background Illustration）</em></p><hr>`,19)),i("p",null,[s[6]||(s[6]=a("via: ",-1)),n(e,{href:"https://jao.io/blog/an-even-better-video-wharf.html"},{default:t(()=>[...s[5]||(s[5]=[a("https://jao.io/blog/an-even-better-video-wharf.html",-1)])]),_:1})]),i("p",null,[s[11]||(s[11]=a("作者：",-1)),n(e,{href:"https://jao.io"},{default:t(()=>[...s[7]||(s[7]=[a("jao",-1)])]),_:1}),s[12]||(s[12]=a(" 選題：",-1)),n(e,{href:"https://github.com/lujun9972"},{default:t(()=>[...s[8]||(s[8]=[a("lujun9972",-1)])]),_:1}),s[13]||(s[13]=a(" 譯者：",-1)),n(e,{href:"https://github.com/Drwhooooo"},{default:t(()=>[...s[9]||(s[9]=[a("Drwhooooo",-1)])]),_:1}),s[14]||(s[14]=a(" 校對：",-1)),n(e,{href:"https://github.com/wxy"},{default:t(()=>[...s[10]||(s[10]=[a("wxy",-1)])]),_:1})]),i("p",null,[s[17]||(s[17]=a("本文由 ",-1)),n(e,{href:"https://github.com/LCTT/TranslateProject"},{default:t(()=>[...s[15]||(s[15]=[a("LCTT",-1)])]),_:1}),s[18]||(s[18]=a(" 原創編譯，",-1)),n(e,{href:"https://linux.cn/"},{default:t(()=>[...s[16]||(s[16]=[a("Linux中國",-1)])]),_:1}),s[19]||(s[19]=a(" 榮譽推出",-1))])])}const C=l(u,[["render",m]]);export{w as __pageData,C as default};
